node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
const categories = [
  { slug: 'featured', title: 'Featured products', products: ['Desk Lamp', 'Wool Blanket'], absent: ['Canvas Tote', 'Travel Mug'] },
  { slug: 'sale', title: 'Products on sale', products: ['Canvas Tote', 'Travel Mug'], absent: ['Desk Lamp', 'Wool Blanket'] },
]
for (const category of categories) {
  const url = `http://localhost:3451/catalog?category=${category.slug}`
  const response = await fetch(url)
  assert.equal(response.status, 200)
  const html = await response.text()
  assert.ok(html.includes(`<h2>${category.title}</h2>`), `${category.slug} heading`)
  for (const product of category.products) assert.ok(html.includes(`<li>${product}</li>`), `${category.slug} product: ${product}`)
  for (const product of category.absent) assert.ok(!html.includes(`<li>${product}</li>`), `${category.slug} excludes: ${product}`)
  console.log(`${url}: ${response.status}; heading and products correct`)
}
EOF

